def button(t,kind=''): return f'<button class="btn {kind}">{t}</button>'
def tag(t,kind=''): return f'<span class="tag {kind}">{t}</span>'
def pill(t,sel=False): return f'<span class="pill {"sel" if sel else ""}">{t}</span>'
def kv(a,b):return f'<div class="kv"><span>{a}</span><span>{b}</span></div>'
def field(t,kind=''):return f'<div class="field {kind}">{t}</div>'
def note(t,warn=False):return f'<div class="note {"warnnote" if warn else ""}">{t}</div>'
def head(title,sub='',actions=''):return f'<div class="head"><div><h1>{title}</h1><div class="sub">{sub}</div></div><div class="row">{actions}</div></div>'
def table(headers,rows):return '<table class="table"><thead><tr>'+''.join('<th>'+c+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def stats(labels,values):return '<div class="stats">'+''.join(f'<div class="stat">{l}<b>{v}</b></div>' for l,v in zip(labels,values))+'</div>'
def art(i=0,seconds='00:04.2',tidy=True):
    bg=['#e2e7d9','#e4ddd3','#dce6ea'][i%3]; box=['#708657','#ad8260','#658895'][i%3]
    return f'''<div class="art"><svg viewBox="0 0 300 230" preserveAspectRatio="xMidYMid slice"><rect width="300" height="230" fill="{bg}"/><path d="M0 180L300 167V230H0Z" fill="#b2b7a5"/><rect x="197" y="40" width="65" height="100" rx="3" fill="white" opacity=".38"/><path d="M229 40V140M197 91H262" stroke="{bg}" stroke-width="4"/><ellipse cx="118" cy="195" rx="85" ry="11" fill="#343e2c" opacity=".14"/><rect x="43" y="117" width="130" height="72" rx="6" fill="{box}"/><path d="M43 135H173" stroke="white" stroke-width="2" opacity=".4"/><rect x="57" y="129" width="39" height="44" rx="3" fill="#f3f1df"/><rect x="106" y="129" width="50" height="44" rx="3" fill="#ecedde"/><path d="M76 125V104M71 125V111M121 125V99M128 125V109" stroke="#67714d" stroke-width="5"/><circle cx="221" cy="70" r="22" fill="#a8a798"/><path d="M191 145C191 98 251 98 251 145V173H191Z" fill="#7c8678"/><path d="M198 119L161 145" stroke="#a8a798" stroke-width="12" stroke-linecap="round"/></svg><span class="play">▷</span><span class="duration">{seconds}</span></div>'''
def video(i=0,label='',seconds='00:04.2'):
    return '<div class="video">'+art(i,seconds)+(f'<div class="caption">{label}</div>' if label else '')+f'<div class="controls">Ⅱ　━━━━━━──　0:00 / {seconds}</div></div>'
def card(title,i,meta,action='提取 Hook',label=''):
    return '<div class="card">'+art(i,'00:18' if action=='提取 Hook' else '00:04.2')+f'<div class="cardbody"><h3>{title}</h3><div class="sub">{meta}</div><div style="margin-top:10px">{tag(label or "反差结果型")}</div><div class="cardfoot"><span>查看详情</span>{button(action,"primary")}</div></div></div>'
def shell(n,title,body,admin=False,discover=False):
    navs=['候选素材','周度发布','效果看板'] if admin else ['灵感发现','周度热门 Hook','我的资产']
    active='效果看板' if n=='F12' else '候选素材' if admin else '周度热门 Hook' if n=='F10' else '灵感发现' if discover else '我的资产'
    nav=''.join(f'<div class="nav {"active" if x==active else ""}">{x}</div>' for x in navs)
    if not admin:nav+='<div class="label">创作工具</div><div class="nav">视频创作</div><div class="nav">生成记录</div>'
    return f'<div class="screen"><aside class="side"><div class="brand"><span class="logo">C</span>CreatiSignal</div><div class="label">{"内容运营" if admin else "工作空间"}</div>{nav}<div class="space">▣　品牌 A 工作空间</div></aside><main class="main"><div class="top"><span>{"运营后台" if admin else "工作空间"}　 /　{title}</span><span>{n}　·　产品原型</span></div><div class="content">{body}</div></main><div class="spec">页面与封面为示意　·　所有名称与数字均为演示数据</div></div>'

