def inline(t):
    return re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',html.escape(t))

def md_html(txt):
    lines=txt.strip().splitlines();out=[];i=0
    while i<len(lines):
        l=lines[i].strip()
        if not l:i+=1;continue
        if l.startswith('# '):out.append('<h1>'+inline(l[2:])+'</h1>')
        elif l.startswith('## '):out.append('<h2>'+inline(l[3:])+'</h2>')
        elif l.startswith('!['):
            m=re.match(r'!\[(.*?)\]\((.*?)\)',l);p=ROOT/m[2]
            if p.exists():out.append('<figure><img src="data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()+'" alt="'+html.escape(m[1])+'"><figcaption>'+html.escape(m[1])+'　静态原型示例</figcaption></figure>')
        elif l.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].strip().startswith('|'):
                row=lines[i].strip()
                if not re.match(r'^\|[\s:|-]+\|$',row):rows.append([c.strip() for c in row.strip('|').split('|')])
                i+=1
            out.append('<table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in rows[1:])+'</tbody></table>');continue
        elif l.startswith('- ') or re.match(r'^\d+\. ',l):
            ordered=bool(re.match(r'^\d+\. ',l));typ='ol' if ordered else 'ul';items=[]
            while i<len(lines) and (bool(re.match(r'^\d+\. ',lines[i].strip())) if ordered else lines[i].strip().startswith('- ')):
                items.append('<li>'+inline(re.sub(r'^(?:\d+\. |- )','',lines[i].strip()))+'</li>');i+=1
            out.append('<'+typ+'>'+''.join(items)+'</'+typ+'>');continue
        else:out.append('<p>'+inline(l)+'</p>')
        i+=1
    return '\n'.join(out)

DOC_CSS='''
@page{size:A4;margin:0}*{box-sizing:border-box}html{background:#e9edef}body{margin:0;color:#24282c;font-family:"Microsoft YaHei",sans-serif;font-size:10pt;line-height:1.7}.page{width:210mm;height:297mm;padding:16mm 17mm;position:relative;background:white;margin:8mm auto;break-after:page;page-break-after:always}.page:last-child{break-after:auto;page-break-after:auto}header{font-size:8pt;color:#000;display:flex;justify-content:space-between;margin-bottom:6mm}h1{font-size:22pt;line-height:1.35;letter-spacing:-.5pt;margin:0 0 5mm;color:black}h2{font-size:12pt;line-height:1.5;margin:4mm 0 2mm;color:black}p{margin:0 0 3mm}ul,ol{padding-left:5mm;margin:0 0 3mm}li{margin-bottom:2mm}figure{margin:3mm 0 4mm}figure img{width:100%;display:block;border:1px solid #e1e5e8;border-radius:1.5mm}figcaption{font-size:7.6pt;color:#808993;margin-top:1.5mm}table{border-collapse:collapse;width:100%;font-size:9pt;line-height:1.65;margin:3mm 0 4mm}td,th{border:1px solid #d9d9d9;text-align:left;vertical-align:middle;padding:2.0mm 2.2mm}th{background:#eaf0f2;color:#000;font-weight:700}tr:nth-child(even) td{background:#fafbfc}th:first-child,td:first-child{min-width:13mm}footer{position:absolute;bottom:8.5mm;left:17mm;right:17mm;display:flex;justify-content:space-between;color:#8d969e;font-size:8pt}.page.feature{font-size:9.5pt;line-height:1.6}.page.feature h1{font-size:20pt;margin-bottom:3mm}.page.feature figure{width:94%;margin:3mm auto}.page.feature h2{margin:3mm 0 1.6mm;font-size:11pt}.page.feature p{margin-bottom:2.5mm}.page.feature li{margin-bottom:1.7mm}.page.dense{font-size:9.5pt;line-height:1.6}.page.dense table{font-size:8.7pt;line-height:1.55}.page.dense th,.page.dense td{padding:1.5mm 2mm}.page.cover h1{font-size:30pt;margin-top:7mm;margin-bottom:8mm}.page.cover h2{margin-top:4.3mm}.page.prompt{font-size:10pt;line-height:1.85}.page.prompt p{margin-bottom:4mm}@media print{html{background:white}.page{margin:0;box-shadow:none}}@media screen{.page{box-shadow:0 2px 20px #18242a13}}
'''

def build_doc():
    text=(ROOT/(NAME+'.md')).read_text(encoding='utf-8');sections=text.split('<!-- page -->');chunks=[]
    for i,s in enumerate(sections):
        cls='page'+(' feature' if '![' in s else '')+(' cover' if i==0 else '')+(' dense' if s.count('|')>45 else '')+(' prompt' if s.startswith('\n\n# Hook 提取系统提示词') or s.startswith('\n\n# Hook 模板输出') else '')
        chunks.append(f'<section class="{cls}" id="page-{i+1}"><header><span>CREATISIGNAL　产品需求</span><span>Hook 资产　V1.0</span></header><div class="pagebody">'+md_html(s)+f'</div><footer><span>2026年9月8日　产品与工程评审</span><span>{i+1:02d} / {len(sections):02d}</span></footer></section>')
    doc='<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><title>Hook资产产品需求文档</title><style>'+DOC_CSS+'</style><body>'+''.join(chunks)+'</body></html>'
    (ROOT/(NAME+'.html')).write_text(doc,encoding='utf-8')
    first=text.split('## 角色和任务\n\n',1)[1].split('<!-- page -->',1)[0]
    second=text.split('## 系统提示词续\n\n',1)[1].split('## 一条资产应达到的表达质量',1)[0]
    prompt='Hook提取系统提示词\n适用模型 Qwen3.7plus\n版本 V1.0\n\n角色和任务\n'+first+'\n'+second
    prompt=re.sub(r'^## ', '', prompt, flags=re.M).strip()+'\n'
    (ROOT/'Qwen3.7plus_Hook提取系统提示词_V1.0.txt').write_text(prompt,encoding='utf-8')
    if all((IMAGES/(k+'.png')).exists() for k in S):
        names={k:re.search(r'<h1>(.*?)</h1>',v).group(1) for k,v in S.items()}
        imgs={k:'data:image/png;base64,'+base64.b64encode((IMAGES/(k+'.png')).read_bytes()).decode() for k in S}
        gallery='''<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><title>Hook资产功能原型</title><style>*{box-sizing:border-box}body{margin:0;background:#e9eded;font-family:"Microsoft YaHei",sans-serif;color:#20282a}header{padding:22px 30px;background:#fff;border-bottom:1px solid #dce2e4}h1{font-size:22px;margin:0 0 8px}p{margin:0;font-size:13px;color:#7b8589}main{display:flex;gap:18px;padding:20px}nav{width:225px;flex:none}button{font:inherit;font-size:13px;text-align:left;background:#fff;border:1px solid #dbe3e6;border-radius:6px;padding:11px;margin:0 0 7px;width:100%;cursor:pointer}button.on{background:#dfe9bd;border-color:#b6c68b}article{min-width:0;flex:1}img{display:block;width:100%;height:auto;border:1px solid #d8e0e3;border-radius:8px}.hint{margin:12px 0;font-size:12px;color:#718085}</style><header><h1>Hook资产功能原型</h1><p>12 个功能模块　点击左侧切换大图　静态示例，不执行真实业务操作</p></header><main><nav id="nav"></nav><article><img id="screen" alt=""><div class="hint">图片内的业务按钮为静态说明；完整需求与验收以同包文档为准。</div></article></main><script>const names=__NAMES__;const imgs=__IMGS__;const nav=document.getElementById('nav');function select(k){document.getElementById('screen').src=imgs[k];document.getElementById('screen').alt=k+' '+names[k];document.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.key===k));}Object.entries(names).forEach(([k,n])=>{const b=document.createElement('button');b.textContent=k+' '+n;b.dataset.key=k;b.onclick=()=>select(k);nav.append(b)});select('F01');</script></html>'''.replace('__NAMES__',json.dumps(names,ensure_ascii=False)).replace('__IMGS__',json.dumps(imgs))
        (ROOT/'Hook资产_功能原型浏览.html').write_text(gallery,encoding='utf-8')
    print(json.dumps({'pages':len(sections),'features':len(S),'characters':len(text),'prompt_chars':len(prompt)},ensure_ascii=False))

if __name__=='__main__':build_doc()
